    # Italic
    t = re.sub(r'\*(.+?)\*', r'<em>\1</em>', t)
    # Inline code
    t = re.sub(r'`(.+?)`', r'<code>\1</code>', t)
    # Numbered list items
    lines = t.split('\n')
    out_lines = []
    in_list = False
    for line in lines:
        stripped = line.strip()
        li_match = re.match(r'^\d+\. (.+)', stripped)
        bullet_match = re.match(r'^[-*] (.+)', stripped)
        if li_match or bullet_match:
            if not in_list:
                out_lines.append('<ol>' if li_match else '<ul>')
                in_list = 'ol' if li_match else 'ul'
            item = li_match.group(1) if li_match else bullet_match.group(1)
            out_lines.append(f'<li>{item}</li>')
        else:
            if in_list:
                out_lines.append(f'</{in_list}>')
                in_list = False
            if stripped:
                out_lines.append(f'<p>{stripped}</p>')
    if in_list:
        out_lines.append(f'</{in_list}>')
    return '\n'.join(out_lines)

