:root {
  --bg: #fafaf8;
  --surface: #ffffff;
  --border: #c8c8c0;
  --text: #1a1a1a;
  --muted: #4a4a45;        /* darkened: was #6b6b65, now passes AA on white */
  --accent: #1e4f78;       /* darkened: was #2c5f8a, now passes AA on white */
  --accent-light: #e4eff7;
  --prompt-bg: #f0f0ec;
  --ts-color: #5a5a55;     /* WCAG AA on white/surface */
